def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 5:
        return 'C'

    my_actions = [h[0] for h in history]
    opp_actions = [h[1] for h in history]

    my_defections = 0
    opp_c = 0
    for i in range(n):
        if my_actions[i] == 'D':
            my_defections += 1
        if opp_actions[i] == 'C':
            opp_c += 1

    opp_coop_rate = opp_c / n

    last_my = my_actions[-1]
    last_opp = opp_actions[-1]

    opp_d_streak = 0
    for i in range(n-1, -1, -1):
        if opp_actions[i] == 'D':
            opp_d_streak += 1
        else:
            break

    cc_streak = 0
    for i in range(n-1, -1, -1):
        if opp_actions[i] == 'C' and my_actions[i] == 'C':
            cc_streak += 1
        else:
            break

    if opp_coop_rate > 0.9:
        return 'D'

    if opp_coop_rate < 0.2:
        return 'D'

    if last_my == 'D' and last_opp == 'C':
        return 'D'

    if last_opp == 'D':
        if opp_d_streak >= 3 and last_my == 'D':
            recent_test = False
            start = max(0, n - 10)
            for i in range(start, n):
                if my_actions[i] == 'C' and opp_actions[i] == 'D':
                    recent_test = True
                    break
            if not recent_test:
                return 'C'
        return 'D'

    if last_my == 'C' and last_opp == 'C':
        if my_defections == 0 and cc_streak >= 10 and n < 90:
            return 'D'
        return 'C'

    return 'C'
